<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $pageTitle='My Profile | StudentHub'; $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$mobile=trim($_POST['mobile']??'');if(mb_strlen($name)<2)$message='Please enter a valid name.';elseif(!preg_match('/^[6-9][0-9]{9}$/',$mobile))$message='Please enter a valid 10-digit mobile number.';elseif(!$pdo)$message='Database connection unavailable.';else{$s=$pdo->prepare('UPDATE users SET name=?,mobile=? WHERE id=?');$s->execute([$name,$mobile,$_SESSION['user_id']]);$_SESSION['name']=$name;$message='Profile updated successfully.';}}
$user=['name'=>$_SESSION['name']??'','email'=>$_SESSION['email']??'','mobile'=>'','course'=>'','year_of_study'=>'','gender'=>''];
if($pdo){$s=$pdo->prepare('SELECT name,email,mobile,course,year_of_study,gender FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$user=array_merge($user,$s->fetch()?:[]);}
include __DIR__.'/includes/header.php';
?>
<main id="main-content"><section class="page-title"><h1>My profile</h1><p>Manage your student information.</p></section><section class="profile-section"><article class="profile-card"><div class="avatar" aria-hidden="true"><?=e(strtoupper(substr($user['name'],0,1)))?></div><h2><?=e($user['name'])?></h2><p><?=e($user['email'])?></p><p class="muted"><?=e($user['course'])?></p></article><article class="profile-details"><h2>Profile details</h2><?php if($message):?><p class="success"><?=e($message)?></p><?php endif;?>
<form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="name">Full name</label><input id="name" name="name" required value="<?=e($user['name'])?>"></div><div class="field"><label for="email">Email (cannot be changed here)</label><input id="email" type="email" disabled value="<?=e($user['email'])?>"></div><div class="field"><label for="mobile">Mobile number</label><input id="mobile" name="mobile" required pattern="[6-9][0-9]{9}" value="<?=e($user['mobile'])?>"></div><p><strong>Course:</strong> <?=e($user['course'])?> · <strong>Year:</strong> <?=e($user['year_of_study'])?></p><button class="btn">Save changes</button></form></article></section></main><?php include __DIR__.'/includes/footer.php'; ?>
